using System.Text.Json;
static class AccountingEndpoints{public static void Map(WebApplication app){var opts=new JsonSerializerOptions(JsonSerializerDefaults.Web);
app.MapGet("/api/state",(SchoolWorkspace workspace)=>{lock(workspace.Gate)return Results.Json(workspace.Data,opts);});
app.MapPost("/api/accounts",(SchoolWorkspace workspace,Account a)=>{lock(workspace.Gate){if(a.Level<1||a.Level>8||workspace.Data.Accounts.Any(x=>x.Code==a.Code)||string.IsNullOrWhiteSpace(a.Name))throw new ArgumentException("Unique code, name and level 1–8 required.");if(a.Level>1&&!workspace.Data.Accounts.Any(x=>x.Code==a.Parent&&x.Level==a.Level-1&&x.Category==a.Category))throw new ArgumentException("Parent must be one level above in the same category.");if(a.Level==1&&a.Parent!=null)throw new ArgumentException("Root cannot have a parent.");if(!new[]{"Asset","Liability","Equity","Revenue","Expense"}.Contains(a.Category))throw new ArgumentException("Invalid account category.");workspace.Data.Accounts.Add(a);workspace.Save();return Results.Ok(a);}});
app.MapPost("/api/cards",(SchoolWorkspace workspace,Card c)=>{lock(workspace.Gate){if(string.IsNullOrWhiteSpace(c.Name)||!new[]{"Customer","Supplier","Employee","Other"}.Contains(c.Type))throw new ArgumentException("Name and valid card type required.");c=c with{Id=Guid.NewGuid().ToString()};workspace.Data.Cards.Add(c);workspace.Save();return Results.Ok(c);}});
app.MapPost("/api/items",(SchoolWorkspace workspace,Item i)=>{lock(workspace.Gate){if(string.IsNullOrWhiteSpace(i.Name)||i.Price<0||!workspace.Data.Accounts.Any(a=>a.Code==i.RevenueAccount&&a.Level==8&&a.Category=="Revenue")||!workspace.Data.Accounts.Any(a=>a.Code==i.ExpenseAccount&&a.Level==8&&a.Category=="Expense"))throw new ArgumentException("Name, nonnegative price and valid revenue/expense leaf accounts required.");i=i with{Id=Guid.NewGuid().ToString()};workspace.Data.Items.Add(i);workspace.Save();return Results.Ok(i);}});
app.MapPut("/api/approvals",(SchoolWorkspace workspace,List<Signatory> s)=>{lock(workspace.Gate){var required=new[]{"Prepared by","Checked by","Verified by","Noted by","Approver"};if(s.Count!=5||required.Any(r=>s.Count(x=>x.Role==r&& !string.IsNullOrWhiteSpace(x.Name))!=1))throw new ArgumentException("Provide each of the five signatory roles once.");workspace.Data.Signatories=s;workspace.Save();return Results.Ok(s);}});
app.MapPut("/api/access",(SchoolWorkspace workspace,List<AccessRule> rules)=>{lock(workspace.Gate){workspace.Data.Access=rules;workspace.Save();return Results.Ok(rules);}});
app.MapPost("/api/documents",(SchoolWorkspace workspace,Document input)=>{lock(workspace.Gate){var types=new[]{"Purchase Request","Purchase Order","Sales Invoice","Collection","Accounts Payable","Disbursement","Adjustment/Journal"};if(!types.Contains(input.Type)||(input.Amount<=0||decimal.Round(input.Amount,2)!=input.Amount)||string.IsNullOrWhiteSpace(input.Memo))throw new ArgumentException("Valid type, description and positive amount required.");if(input.Type!="Adjustment/Journal"&&!workspace.Data.Cards.Any(c=>c.Id==input.CardId))throw new ArgumentException("Select a card.");var parents=new Dictionary<string,string>{{"Purchase Order","Purchase Request"},{"Collection","Sales Invoice"},{"Disbursement","Accounts Payable"}};if(parents.TryGetValue(input.Type,out var pt)){var parent=workspace.Data.Documents.SingleOrDefault(d=>d.Id==input.SourceId&&d.Type==pt);if(parent==null)throw new ArgumentException("Select the related "+pt+".");if(parent.CardId!=input.CardId)throw new ArgumentException("Card must match the source document.");if(pt!="Purchase Request"&&parent.Status!="Posted")throw new ArgumentException("Post the source document first.");var used=workspace.Data.Documents.Where(d=>d.SourceId==parent.Id).Sum(d=>d.Amount);if(used+input.Amount>parent.Amount)throw new ArgumentException("Amount exceeds the source document's remaining balance.");}else if(input.SourceId!=null)throw new ArgumentException("This document type does not accept a source.");var d=input with{Id=Guid.NewGuid().ToString(),Number=$"{Seed.Prefix(input.Type)}-{workspace.Data.Documents.Count+1:0000}",Status="Draft",ApprovalNames=new(workspace.Data.Signatories)};workspace.Data.Documents.Add(d);workspace.Save();return Results.Ok(d);}});
app.MapPost("/api/documents/{id}/post",(SchoolWorkspace workspace,string id)=>{lock(workspace.Gate){var d=workspace.Data.Documents.SingleOrDefault(x=>x.Id==id)??throw new ResourceNotFoundException();if(d.Status=="Posted")throw new ArgumentException("Already posted.");if(d.Type is "Purchase Request" or "Purchase Order")throw new ArgumentException("PR and PO are nonposting documents.");var lines=d.Lines;if(lines.Count<2||lines.Any(l=>l.Debit<0||l.Credit<0||decimal.Round(l.Debit,2)!=l.Debit||decimal.Round(l.Credit,2)!=l.Credit||(l.Debit>0)==(l.Credit>0)||!workspace.Data.Accounts.Any(a=>a.Code==l.Account&&a.Level==8)))throw new ArgumentException("Use at least two valid level-eight accounts with one positive debit or credit per line.");if(lines.Sum(l=>l.Debit)!=lines.Sum(l=>l.Credit)||lines.Sum(l=>l.Debit)!=d.Amount)throw new ArgumentException("Debits and credits must balance and equal document amount.");if(lines.Any(l=>l.CardId!=null&&!workspace.Data.Cards.Any(c=>c.Id==l.CardId)))throw new ArgumentException("Unknown card in journal line.");workspace.Data.Documents[workspace.Data.Documents.IndexOf(d)]=d with{Status="Posted"};workspace.Save();return Results.Ok();}});
app.MapGet("/api/reports/{report}",(SchoolWorkspace workspace,string report,DateOnly? from,DateOnly? to,string? account,string? card)=>{lock(workspace.Gate){if(!new[]{"trial-balance","balance-sheet","general-ledger","subsidiary-ledger"}.Contains(report))throw new ArgumentException("Unknown report.");if(from>to)throw new ArgumentException("From date must precede to date.");var all=workspace.Data.Documents.Where(d=>d.Status=="Posted"&&(!to.HasValue||d.Date<=to)).SelectMany(d=>d.Lines.Select(l=>new{d.Date,d.Number,d.Memo,l.Account,CardId=l.CardId??d.CardId,l.Debit,l.Credit})).ToList();all=all.Where(l=>(account==null||l.Account==account)&&(card==null||l.CardId==card)).ToList();var entries=all.Where(l=>(!from.HasValue||l.Date>=from)&& (account==null||l.Account==account)&&(card==null||l.CardId==card)).OrderBy(l=>l.Date).ThenBy(l=>l.Number).ToList();var balances=workspace.Data.Accounts.Where(a=>a.Level==8).Select(a=>{var period=entries.Where(l=>l.Account==a.Code);var cumulative=all.Where(l=>l.Account==a.Code);var opening=all.Where(l=>l.Account==a.Code&&from.HasValue&&l.Date<from);return new{a.Code,a.Name,a.Category,Debit=period.Sum(l=>l.Debit),Credit=period.Sum(l=>l.Credit),Opening=opening.Sum(l=>l.Debit-l.Credit),Balance=cumulative.Sum(l=>l.Debit-l.Credit)};}).ToList();var assets=balances.Where(a=>a.Category=="Asset").Sum(a=>a.Balance);var liabilities=-balances.Where(a=>a.Category=="Liability").Sum(a=>a.Balance);var equity=-balances.Where(a=>a.Category=="Equity").Sum(a=>a.Balance);var earnings=-balances.Where(a=>a.Category is "Revenue" or "Expense").Sum(a=>a.Balance);return Results.Ok(new{report,from,to,entries,balances,totals=new{debit=entries.Sum(l=>l.Debit),credit=entries.Sum(l=>l.Credit),assets,liabilities,equity,earnings,difference=assets-liabilities-equity-earnings}});}});
}}
